ALTER TABLE t_p13776910_data_analytics_solut.portfolio_projects ADD COLUMN IF NOT EXISTS description TEXT NOT NULL DEFAULT '';
UPDATE t_p13776910_data_analytics_solut.portfolio_projects SET description = 'АСУБТ — Автоматизированная система управления безопасностью труда. Проведение Поведенческого Аудита Безопасности (ПАБ), Проведение Производственного Контроля (ПК), электронный контроль устранения нарушений и замечаний, а также электронное управление и контроль работы отдела, службы и многое другое. Несколько программ в одной. По заявке откроем нужные Вам направления. Данная программа подойдет тому, кто идет со временем в ногу, для кого безопасность предприятия прежде всего. В программе можно открыть еще не один блок. Техническое задание предоставляет пользователь, по которому рассчитывается сумма и время на выполнение заказа. Время выполнения зависит от сложности и наполняемости программы.', category = 'Охрана труда и промышленная безопасность', tech = 'ПАБ / Производственный контроль / Контроль устранения нарушений', updated_at = NOW() WHERE id = 1;
UPDATE t_p13776910_data_analytics_solut.portfolio_projects SET description = 'Горный контроль — система учёта и контроля персонала (и не только) на руднике. Профессиональный корпоративный веб-сайт с современным дизайном, адаптивной версткой и системой управления контентом.', category = 'Горно-рудная промышленность', tech = 'Учёт и контроль персонала на руднике', updated_at = NOW() WHERE id = 2;